import { NextResponse } from "next/server";
import { writeFile, unlink } from "fs/promises";
import path from "path";
import { execFile } from "child_process";
import { promisify } from "util";
import plants from "../../data/plants.json";

const execFileAsync = promisify(execFile);

export async function POST(request) {
  let imagePath = null;

  try {
    const body = await request.json();

    if (!body.image) {
      return NextResponse.json(
        { error: "No image provided" },
        { status: 400 }
      );
    }

    // Convert base64 image to buffer
    const base64Data = body.image.replace(
      /^data:image\/\w+;base64,/,
      ""
    );

    const imageBuffer = Buffer.from(
      base64Data,
      "base64"
    );

    // Temporary image
    imagePath = path.join(
      process.cwd(),
      "temp-plant-image.jpg"
    );

    await writeFile(
      imagePath,
      imageBuffer
    );

    // Path to medicinal_plant_model
    const modelDir = path.join(
      process.cwd(),
      "..",
      "..",
      "medicinal_plant_model"
    );

    const pythonScript = path.join(
      modelDir,
      "predict.py"
    );

    // Run Python prediction
    const { stdout, stderr } =
      await execFileAsync(
        "python",
        [
          pythonScript,
          imagePath
        ],
        {
          cwd: modelDir,
        }
      );

    console.log(
      "Python output:",
      stdout
    );

    if (stderr) {
      console.log(
        "Python stderr:",
        stderr
      );
    }

    // Parse Python JSON
    const result = JSON.parse(
      stdout.trim()
    );

    const plantName = result.plant;

    /*
     * Find matching plant in plants.json
     *
     * Handles small differences such as:
     * Tulasi
     * tulasi
     * TULASI
     */
    const plantData = plants.find(
      (plant) =>
        plant.name?.toLowerCase() ===
        plantName?.toLowerCase()
    );

    return NextResponse.json({
      plant: plantName,

      confidence: result.confidence,

      properties:
        plantData?.properties ||
        "No plant information available.",

      plantData: plantData || null,
    });

  } catch (error) {

    console.error(
      "Prediction error:",
      error
    );

    return NextResponse.json(
      {
        error:
          error.message ||
          "Prediction failed"
      },
      {
        status: 500
      }
    );

  } finally {

    // Delete temporary image
    if (imagePath) {
      try {
        await unlink(imagePath);
      } catch {}
    }

  }
}